#include <ActivePictureEvidence.h>
#include <vprenderer/AlphaSourceCropPolicy.h>
#include <vprenderer/BufferedPictureExpansion.h>
#include <array>
#include <iostream>
using namespace AlphaSourceCrop;
static ActivePictureBounds Scope(){return {0,276,3840,1884,3840,2160,3840.0/1608,ActivePictureBounds::BarAxes::TOP_BOTTOM};}
static ActivePictureBounds Target(){return {0,68,3840,2092,3840,2160,3840.0/2024,ActivePictureBounds::BarAxes::TOP_BOTTOM};}
static ActivePictureEvidence NativeEvidence(){ActivePictureEvidence e;e.available=true;e.classification=ActivePictureClassification::BAR_CROP_TRUSTED;e.authorityOrigin=ActivePictureAuthorityOrigin::NATIVE;e.trustedBounds=Target();e.proposedBounds=Target();e.top.trusted=e.bottom.trusted=true;e.axisEvidence.vertical.scanComplete=true;e.axisEvidence.vertical.state=ActivePictureAxisState::TRUSTED_BARS;return e;}
static ActivePicturePresentationRetentionEvidence Retention(bool native,bool broad){ActivePicturePresentationRetentionEvidence r;r.analysisValid=r.presentationValid=r.expansionStripsAvailable=true;r.expansionBase=Scope();r.expansionCandidate=Target();r.activePicture=NativeEvidence();auto set=[&](ActivePictureEdgeEvidence& e){e.barPixels=208;e.distributedSupportDepthRowsByQuartile.fill(native?0x3f:0);if(native){e.blackFraction=.04;e.continuity=0;e.lumaP90=36;e.texture=7.1;}if(broad){e.blackFraction=.30;e.continuity=.40;e.lumaP90=200;e.texture=20;}};set(r.expandingTop);set(r.expandingBottom);return r;}
static void Live(const char* label){OutwardPictureConfirmationState s;const bool native[3]={true,true,true},broad[3]={false,true,false};for(int i=0;i<3;++i){auto d=ConfirmOutwardPictureTransition(s,Scope(),Target(),Retention(native[i],broad[i]),7,100+i);s=d.state;std::cout<<label<<" frame="<<(100+i)<<" broad="<<d.broadOpposingPicture<<" native="<<d.nativeDistributedPicture<<" votes="<<d.state.confirmations<<" authoritative="<<d.authoritative<<"\n";if(i==1){auto repeat=ConfirmOutwardPictureTransition(s,Scope(),Target(),Retention(true,true),7,101);s=repeat.state;std::cout<<label<<" repeated-frame=101 votes="<<s.confirmations<<" authoritative="<<repeat.authoritative<<"\n";}}auto repeat=ConfirmOutwardPictureTransition(s,Scope(),Target(),Retention(true,true),7,102);std::cout<<label<<" repeated-frame=102 votes="<<repeat.state.confirmations<<" authoritative="<<repeat.authoritative<<"\n";}
static BufferedPictureExpansionProof Queue(bool alternate){std::array<BufferedPictureExpansionSample,3> s{};for(int i=0;i<3;++i){const uint64_t seq=100+i;s[i].identity={7,seq,seq,seq*417083,11,13,17};s[i].observation={Target(),seq,true,ActivePictureClassification::BAR_CROP_TRUSTED,24};s[i].retention=alternate?Retention(i!=1,i==1):Retention(true,false);s[i].nearBlackEvaluated=true;}return BuildBufferedPictureExpansion(s.data(),s.size(),Scope(),2,2,19,23);}
int main(){Live("live");auto q=Queue(false);std::cout<<"queue-native valid="<<q.valid<<" first="<<q.decision.effectiveIdentity.acceptedSequence<<"\n";auto a=Queue(true);std::cout<<"queue-alternating valid="<<a.valid<<" first="<<a.decision.effectiveIdentity.acceptedSequence<<"\n";return 0;}
